//! Bounded prototype: pack twelve input rows without changing FMA order.
use super::*;
use std::arch::aarch64::*;
use super::tests::{values, oracle, assert_bits};

#[allow(clippy::too_many_arguments)]
fn packed_execute(input: &[f32], bias: &[f32], packed: &PackedMatrix, output: &mut [f32], first: usize, inner: usize, columns: usize, scratch: &mut [f32], store: &impl StoreTransform) {
    assert!(scratch.len() >= 48 * inner);
    let rows = output.len() / columns;
    for group in (0..rows).step_by(48) {
        let count = (rows - group).min(48);
        for tile in (0..count).step_by(12) {
            let destination = &mut scratch[tile * inner..(tile + 12) * inner];
            for k in 0..inner {
                for r in 0..12 {
                    destination[k * 12 + r] = input[(first + group + (tile + r).min(count - 1)) * inner + k];
                }
            }
        }
        for (block, panel) in packed.data().chunks_exact(inner * 16).enumerate() {
            for half in 0..2 {
                let column = block * 16 + half * 8;
                if column >= columns { continue; }
                let seed = [initial::<4>(bias, column), initial::<4>(bias, column + 4)];
                for tile in (0..count).step_by(12) {
                    // SAFETY: checked packed spans contain twelve rows and a full sixteen-column panel.
                    let sums = unsafe { packed_tile(&scratch[tile * inner..(tile + 12) * inner], panel, half * 8, seed) };
                    for (r, values) in sums.iter().take(count - tile).enumerate() {
                        for (v, &sum) in values.iter().enumerate() {
                            store_row(sum, output, group + tile + r, column + v * 4, columns, first, store);
                        }
                    }
                }
            }
        }
    }
}

