#[test]
fn packed_rows_preserve_order_tails_and_offsets() {
    for (rows, inner, columns) in [(1,1,1),(11,7,17),(12,17,16),(13,65,33),(47,129,65),(48,384,97),(49,513,17),(61,385,129)] {
        let input=values((rows+3)*inner, 3);
        let weights=values(inner*columns,5);
        let bias=values(columns,7);
        let packed=PackedMatrix::new(&weights, inner, columns).unwrap();
        let mut scratch=vec![0.;48*inner];
        for bias in [bias.as_slice(), &[]] {
            let mut expected=oracle(Backend::NeonFma, &input, &weights, bias, inner, columns);
            for (i,v) in expected.iter_mut().enumerate() { *v=IndexStore.scalar(*v,i); }
            let sentinel=f32::from_bits(0x7fc0_1234);
            let mut actual=vec![sentinel; rows*columns+6];
            packed_execute(&input,bias,&packed,&mut actual[3..3+rows*columns],3,inner,columns,&mut scratch,&IndexStore);
            assert_bits(&actual[3..3+rows*columns], &expected[3*columns..], "packed rows offset");
            assert!(actual[..3].iter().chain(&actual[3+rows*columns..]).all(|v|v.to_bits()==sentinel.to_bits()));
        }
    }
}

#[test]
#[ignore = "local ARM64 release comparison: three shapes, one warm-up and three single-call samples per variant; external timeout 10s"]
fn packed_rows_comparison() {
    assert!(!cfg!(debug_assertions));
    let deadline=std::time::Instant::now();
    for (shape,(rows,inner,columns)) in [(96,384,768),(960,512,1024),(480,1536,768)].into_iter().enumerate() {
        let input=values(rows*inner,3); let weights=values(inner*columns,5);let bias=values(columns,7);
        let packed=PackedMatrix::new(&weights,inner,columns).unwrap();
        let mut scratch=vec![0.;48*inner];
        let mut outputs=[vec![0.;rows*columns],vec![0.;rows*columns]];
        let mut run=|variant,output:&mut [f32]| {
            if variant==0 { execute(Backend::NeonFma,&input,&bias,&packed,output,0,inner,columns,&IdentityStore); }
            else { packed_execute(&input,&bias,&packed,output,0,inner,columns,&mut scratch,&IdentityStore); }
        };
        for (v,o) in outputs.iter_mut().enumerate() {run(v,o);}
        assert_bits(&outputs[1],&outputs[0],"warmup");
        let mut samples=[[0.;3];2];
        for sample in 0..3 {
            for v in if (sample+shape)%2==0 {[0,1]}else{[1,0]} {
                let t=std::time::Instant::now(); run(v,std::hint::black_box(&mut outputs[v]));
                samples[v][sample]=t.elapsed().as_secs_f64()*1000.;
            }
            assert_bits(&outputs[1],&outputs[0],"measured");
            assert!(deadline.elapsed().as_secs_f64()<10.);
        }
        println!("packed_rows {}",serde_json::json!({"rows":rows,"inner":inner,"columns":columns,"control_ms":samples[0],"packed_ms":samples[1],"warmups":1,"samples":3,"calls_per_sample":1,"output_bits_equal":true,"scratch_bytes":scratch.len()*4}));
    }
}

struct IndexStore;
impl StoreTransform for IndexStore {
 fn scalar(&self,value:f32,index:usize)->f32 {value+(index%97) as f32/127.}
 fn vector<const N:usize>(&self,value:Simd<f32,N>,index:usize)->Simd<f32,N> {value+Simd::from_array(std::array::from_fn(|i|((index+i)%97) as f32/127.))}
}

