#[allow(clippy::too_many_arguments)]
fn sme_execute(input: &[f32], bias: &[f32], packed: &PackedMatrix, output: &mut [f32], first: usize, inner: usize, columns: usize, scratch: &mut [f32], store: &impl StoreTransform) {
    assert!(std::arch::is_aarch64_feature_detected!("sme"));
    assert!(scratch.len() >= 64 * inner);
    let rows = output.len() / columns;
    for group in (0..rows).step_by(64) {
        let count = (rows - group).min(64);
        for t in (0..count).step_by(16) {
            let destination = &mut scratch[t * inner..(t + 16) * inner];
            for k in 0..inner {
                for r in 0..16 { destination[k * 16 + r] = input[(first + group + (t + r).min(count - 1)) * inner + k]; }
            }
        }
        for (block, panel) in packed.data().chunks_exact(inner * 16).enumerate() {
            let column=block*16;
            let seed: [f32;16] = std::array::from_fn(|v|bias.get(column+v).copied().unwrap_or(0.));
            for t in (0..count).step_by(16) {
                let mut sums=[0f32;256];
                // SAFETY: all input tiles, packed weights, seed and output lengths are checked above.
                assert!(unsafe { tile(scratch[t*inner..].as_ptr(),panel.as_ptr(),seed.as_ptr(),sums.as_mut_ptr(),inner) });
                for r in 0..(count-t).min(16) {
                    for v in 0..4 {
                        store_row(Simd::<f32,4>::from_slice(&sums[r*16+v*4..]),output,group+t+r,column+v*4,columns,first,store);
                    }
                }
            }
        }
    }
}
